import{_ as l,a0 as p,w as d,s as a,I as i,x as t,a1 as o,A as r,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"怎樣在CentOS 7.0上安裝和配置VNC服務器 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在CentOS 7.0上安裝和配置VNC服務器 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在CentOS 7.0上安裝和配置VNC服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在CentOS 7.0上安裝和配置VNC服務器 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150205 How To Install or Configure VNC Server On CentOS 7.0","title":"怎樣在CentOS 7.0上安裝和配置VNC服務器","tag":"201504","desc":""},"relativePath":"201504/20150205 How To Install or Configure VNC Server On CentOS 7.0.md","filePath":"[post].md"}'),c={name:"201504/20150205 How To Install or Configure VNC Server On CentOS 7.0.md"};function u(C,e,m,g,v,V){const n=p("Link");return d(),a("div",null,[e[26]||(e[26]=i("h1",{id:"怎樣在centos-7-0上安裝和配置vnc服務器",tabindex:"-1"},[t("怎樣在CentOS 7.0上安裝和配置VNC服務器 "),i("a",{class:"header-anchor",href:"#怎樣在centos-7-0上安裝和配置vnc服務器","aria-label":"Permalink to “怎樣在CentOS 7.0上安裝和配置VNC服務器”"},"​")],-1)),i("p",null,[e[2]||(e[2]=t("這是一個關於怎樣在你的 CentOS 7 上安裝配置 ",-1)),o(n,{href:"http://en.wikipedia.org/wiki/Virtual_Network_Computing"},{default:r(()=>[...e[0]||(e[0]=[t("VNC",-1)])]),_:1}),e[3]||(e[3]=t(" 服務的教程。當然這個教程也適合 RHEL 7 。在這個教程裏，我們將學習什麼是 VNC 以及怎樣在 CentOS 7 上安裝配置 ",-1)),o(n,{href:"http://en.wikipedia.org/wiki/Virtual_Network_Computing"},{default:r(()=>[...e[1]||(e[1]=[t("VNC 服務器",-1)])]),_:1}),e[4]||(e[4]=t("。",-1))]),e[27]||(e[27]=s('<p>我們都知道，作為一個系統管理員，大多數時間是通過網絡管理服務器的。在管理服務器的過程中很少會用到圖形界面，多數情況下我們只是用 SSH 來完成我們的管理任務。在這篇文章裏，我們將配置 VNC 來提供一個連接我們 CentOS 7 服務器的方法。VNC 允許我們開啓一個遠程圖形會話來連接我們的服務器，這樣我們就可以通過網絡遠程訪問服務器的圖形界面了。</p><p>VNC 服務器是一個自由開源軟件，它可以讓用户可以遠程訪問服務器的桌面環境。另外連接 VNC 服務器需要使用 VNC viewer 這個客户端。</p><p>** 一些 VNC 服務器的優點：**</p><ul><li>遠程的圖形管理方式讓工作變得簡單方便。</li><li>剪貼板可以在 CentOS 服務器主機和 VNC 客户端機器之間共享。</li><li>CentOS 服務器上也可以安裝圖形工具，讓管理能力變得更強大。</li><li>只要安裝了 VNC 客户端，通過任何操作系統都可以管理 CentOS 服務器了。</li><li>比 ssh 圖形轉發和 RDP 連接更可靠。</li></ul><p>那麼，讓我們開始安裝 VNC 服務器之旅吧。我們需要按照下面的步驟一步一步來搭建一個可用的 VNC。</p><p>首先，我們需要一個可用的桌面環境（X-Window），如果沒有的話要先安裝一個。</p><p><strong>注意：以下命令必須以 root 權限運行。要切換到 root ，請在終端下運行“sudo -s”，當然不包括雙引號（“”）</strong></p><h3 id="_1-安裝-x-window" tabindex="-1">1. 安裝 X-Window <a class="header-anchor" href="#_1-安裝-x-window" aria-label="Permalink to “1. 安裝 X-Window”">​</a></h3>',8)),i("p",null,[e[6]||(e[6]=t("首先我們需要安裝 ",-1)),o(n,{href:"http://en.wikipedia.org/wiki/X_Window_System"},{default:r(()=>[...e[5]||(e[5]=[t("X-Window",-1)])]),_:1}),e[7]||(e[7]=t("，在終端中運行下面的命令，安裝會花費一點時間。",-1))]),e[28]||(e[28]=s(`<pre><code># yum check-update
# yum groupinstall &quot;X Window System&quot;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/installing-x-windows.png" alt="installing x windows"></p><pre><code>#yum install gnome-classic-session gnome-terminal nautilus-open-terminal control-center liberation-mono-fonts
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/gnome-classic-session-install.png" alt="install gnome classic session"></p><pre><code>### 設置默認啓動圖形界面
# unlink /etc/systemd/system/default.target
# ln -sf /lib/systemd/system/graphical.target /etc/systemd/system/default.target
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/configuring-graphics.png" alt="configuring graphics"></p><pre><code># reboot
</code></pre><p>在服務器重啓之後，我們就有了一個工作着的 CentOS 7 桌面環境了。</p><p>現在，我們要在服務器上安裝 VNC 服務器了。</p><h3 id="_2-安裝-vnc-服務器" tabindex="-1">2. 安裝 VNC 服務器 <a class="header-anchor" href="#_2-安裝-vnc-服務器" aria-label="Permalink to “2. 安裝 VNC 服務器”">​</a></h3><p>現在要在我們的 CentOS 7 上安裝 VNC 服務器了。我們需要執行下面的命令。</p><pre><code># yum install tigervnc-server -y
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/install-tigervnc.png" alt="vnc server"></p><h3 id="_3-配置-vnc" tabindex="-1">3. 配置 VNC <a class="header-anchor" href="#_3-配置-vnc" aria-label="Permalink to “3. 配置 VNC”">​</a></h3><p>然後，我們需要在 <code>/etc/systemd/system/</code> 目錄裏創建一個配置文件。我們可以將 <code>/lib/systemd/sytem/vncserver@.service</code> 拷貝一份配置文件範例過來。</p><pre><code># cp /lib/systemd/system/vncserver@.service /etc/systemd/system/vncserver@:1.service
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/copying-configuration.png" alt="copying vnc server configuration"></p><p>接着我們用自己最喜歡的編輯器（這兒我們用的 <strong>nano</strong> ）打開 <code>/etc/systemd/system/vncserver@:1.service</code> ，找到下面這幾行，用自己的用户名替換掉 <code>&lt;USER&gt;</code> 。舉例來説，我的用户名是 linoxide 所以我用 linoxide 來替換掉 <code>&lt;USER&gt;</code> ：</p><pre><code>ExecStart=/sbin/runuser -l &lt;USER&gt; -c &quot;/usr/bin/vncserver %i&quot;
PIDFile=/home/&lt;USER&gt;/.vnc/%H%i.pid
</code></pre><p>替換成</p><pre><code>ExecStart=/sbin/runuser -l linoxide -c &quot;/usr/bin/vncserver %i&quot;
PIDFile=/home/linoxide/.vnc/%H%i.pid
</code></pre><p>如果是 root 用户則</p><pre><code>ExecStart=/sbin/runuser -l root -c &quot;/usr/bin/vncserver %i&quot;
PIDFile=/root/.vnc/%H%i.pid
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/configuring-user.png" alt="configuring user"></p><p>好了，下面重啓 systemd 。</p><pre><code># systemctl daemon-reload
</code></pre><p>最後還要設置一下用户的 VNC 密碼。要設置某個用户的密碼，必須要有能通過 sudo 切換到用户的權限，這裏我用 linoxide 的權限，執行“<code>su linoxide</code>”就可以了。</p><pre><code># su linoxide
$ sudo vncpasswd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/vncpassword.png" alt="setting vnc password"></p><p><strong>確保你輸入的密碼多於6個字符</strong></p><h3 id="_4-開啓服務" tabindex="-1">4. 開啓服務 <a class="header-anchor" href="#_4-開啓服務" aria-label="Permalink to “4. 開啓服務”">​</a></h3><p>用下面的命令（永久地）開啓服務：</p><pre><code>$ sudo systemctl enable vncserver@:1.service
</code></pre><p>啓動服務。</p><pre><code>$ sudo systemctl start vncserver@:1.service
</code></pre><h3 id="_5-防火牆設置" tabindex="-1">5. 防火牆設置 <a class="header-anchor" href="#_5-防火牆設置" aria-label="Permalink to “5. 防火牆設置”">​</a></h3><p>我們需要配置防火牆來讓 VNC 服務正常工作。</p><pre><code>$ sudo firewall-cmd --permanent --add-service vnc-server
$ sudo systemctl restart firewalld.service
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/allowing-firewalld.png" alt="allowing firewalld"></p><p>現在就可以用 IP 和端口號（LCTT 譯註：例如 192.168.1.1:1 ，這裏的端口不是服務器的端口，而是視 VNC 連接數的多少從1開始排序）來連接 VNC 服務器了。</p><h3 id="_6-用-vnc-客户端連接服務器" tabindex="-1">6. 用 VNC 客户端連接服務器 <a class="header-anchor" href="#_6-用-vnc-客户端連接服務器" aria-label="Permalink to “6. 用 VNC 客户端連接服務器”">​</a></h3><p>好了，現在已經完成了 VNC 服務器的安裝了。要使用 VNC 連接服務器，我們還需要一個在本地計算機上安裝的僅供連接遠程計算機使用的 VNC 客户端。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/vncviewer.png" alt="remote access vncserver from vncviewer"></p>`,43)),i("p",null,[e[10]||(e[10]=t("你可以用像 ",-1)),o(n,{href:"http://www.tightvnc.com/"},{default:r(()=>[...e[8]||(e[8]=[t("Tightvnc viewer",-1)])]),_:1}),e[11]||(e[11]=t(" 和 ",-1)),o(n,{href:"https://www.realvnc.com/"},{default:r(()=>[...e[9]||(e[9]=[t("Realvnc viewer",-1)])]),_:1}),e[12]||(e[12]=t(" 的客户端來連接到服務器。",-1))]),e[29]||(e[29]=s(`<p>要用更多的用户連接，需要創建配置文件和端口，請回到第3步，添加一個新的用户和端口。你需要創建 <code>vncserver@:2.service</code> 並替換配置文件裏的用户名和之後步驟裏相應的文件名、端口號。<strong>請確保你登錄 VNC 服務器用的是你之前配置 VNC 密碼的時候使用的那個用户名</strong>。</p><p>VNC 服務本身使用的是5900端口。鑑於有不同的用户使用 VNC ，每個人的連接都會獲得不同的端口。配置文件名裏面的數字告訴 VNC 服務器把服務運行在5900的子端口上。在我們這個例子裏，第一個 VNC 服務會運行在5901（5900 + 1）端口上，之後的依次增加，運行在5900 + x 號端口上。其中 x 是指之後用户的配置文件名 <code>vncserver@:x.service</code> 裏面的 x 。</p><p>在建立連接之前，我們需要知道服務器的 IP 地址和端口。IP 地址是一台計算機在網絡中的獨特的識別號碼。我的服務器的 IP 地址是96.126.120.92，VNC 用户端口是1。</p><p>執行下面的命令可以獲得服務器的公網 IP 地址（LCTT 譯註：如果你的服務器放在內網或使用動態地址的話，可以這樣獲得其公網 IP 地址）。</p><pre><code># curl -s checkip.dyndns.org|sed -e &#39;s/.*Current IP Address: //&#39; -e &#39;s/&lt;.*$//&#39;
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>好了，現在我們已經在運行 CentOS 7 / RHEL 7 的服務器上安裝配置好了 VNC 服務器。VNC 是自由開源軟件中最簡單的一種能實現遠程控制服務器的工具，也是一款優秀的 Teamviewer Remote Access 替代品。VNC 允許一個安裝了 VNC 客户端的用户遠程控制一台安裝了 VNC 服務的服務器。下面還有一些經常使用的相關命令。好好玩！</p><h4 id="其他命令" tabindex="-1">其他命令： <a class="header-anchor" href="#其他命令" aria-label="Permalink to “其他命令：”">​</a></h4><ul><li><p>關閉 VNC 服務。</p><pre><code>  # systemctl stop vncserver@:1.service
</code></pre></li><li><p>禁止 VNC 服務開機啓動。</p><pre><code>  # systemctl disable vncserver@:1.service
</code></pre></li><li><p>關閉防火牆。</p><pre><code>  # systemctl stop firewalld.service
</code></pre></li></ul><hr>`,10)),i("p",null,[e[14]||(e[14]=t("via: ",-1)),o(n,{href:"http://linoxide.com/linux-how-to/install-configure-vnc-server-centos-7-0/"},{default:r(()=>[...e[13]||(e[13]=[t("http://linoxide.com/linux-how-to/install-configure-vnc-server-centos-7-0/",-1)])]),_:1})]),i("p",null,[e[18]||(e[18]=t("作者：",-1)),o(n,{href:"http://linoxide.com/author/arunp/"},{default:r(()=>[...e[15]||(e[15]=[t("Arun Pyasi",-1)])]),_:1}),e[19]||(e[19]=t(" 譯者：",-1)),o(n,{href:"https://github.com/boredivan"},{default:r(()=>[...e[16]||(e[16]=[t("boredivan",-1)])]),_:1}),e[20]||(e[20]=t(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:r(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[23]||(e[23]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[21]||(e[21]=[t("LCTT",-1)])]),_:1}),e[24]||(e[24]=t(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:r(()=>[...e[22]||(e[22]=[t("Linux中國",-1)])]),_:1}),e[25]||(e[25]=t(" 榮譽推出",-1))])])}const x=l(c,[["render",u]]);export{f as __pageData,x as default};
